            new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Proust", Text = "Les êtres nous sont d'habitude si indifférents que, quand nous avons mis dans l'un d'eux de telles possibilités de souffrance et de joie pour nous, il nous semble appartenir à un autre univers, il s'entoure de poésie, il fait de notre vie comme une étendue émouvante où il sera plus ou moins rapproché de nous.", Author = "Marcel Proust" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Proust", Text = "Les lieux que nous avons connus n’appartiennent pas qu’au monde de l’espace où nous les situons pour plus de facilité. Ils n’étaient qu’une mince tranche au milieu d’impressions contiguës qui formaient notre vie d’alors ; le souvenir d’une certaine image n’est que le regret d’un certain instant ; et les maisons, les routes, les avenues, sont fugitives, hélas ! comme les années.", Author = "Marcel Proust" },
