            new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Proust", Text = "Il y a dans notre âme des choses auxquelles nous ne savons pas combien nous tenons. Ou bien, si nous vivons sans elles, c'est parce que nous remettons de jour en jour, par peur d'échouer ou de souffrir, d'entrer en leur possession.", Author = "Marcel Proust" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Proust", Text = "La force qui fait le plus de fois le tour de la terre en une seconde, ce n'est pas l'électricité, c'est la douleur.", Author = "Marcel Proust" },
