            new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Proust", Text = "On désire être compris, parce qu'on désire être aimé, et on désire être aimé parce qu'on aime. La compréhension des autres est indifférente et leur amour importun.", Author = "Marcel Proust" },
